import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../../server/db/migrations-flaretune/', import.meta.url);
const output = new URL('../../server/src/instance/migrationBundle.generated.js', import.meta.url);
const names = [
  '0001_baseline.sql',
  '0002_expand_playlist_count.sql',
  '0003_upgrade_assistant_model.sql',
  '0004_remove_system_playlists.sql',
  '0005_collection_identity.sql',
  '0006_ai_model_profiles.sql',
  '0007_default_ai_guidance.sql',
  '0008_assistant_memory.sql',
  '0009_ai_protocols.sql',
  '0010_user_images.sql',
  '0011_ai_feature_models.sql',
  '0012_google_login.sql',
  '0013_hotpath_indexes_and_counts.sql',
];

// Split checked-in SQL once at build time. A trigger body contains semicolons;
// its final END is the statement boundary. Quoted strings and comments are
// scanned so punctuation in migration text cannot become a new statement.
export function splitSqlStatements(sql) {
  const statements = [];
  let start = 0;
  let quote = null;
  let comment = null;
  let trigger = false;
  for (let i = 0; i < sql.length; i += 1) {
    const char = sql[i];
    const next = sql[i + 1];
    if (comment === 'line') {
      if (char === '\n') comment = null;
      continue;
    }
    if (comment === 'block') {
      if (char === '*' && next === '/') { comment = null; i += 1; }
      continue;
    }
    if (quote) {
      if (char === quote) {
        if (next === quote) i += 1;
        else quote = null;
      }
      continue;
    }
    if (char === '-' && next === '-') { comment = 'line'; i += 1; continue; }
    if (char === '/' && next === '*') { comment = 'block'; i += 1; continue; }
    if (char === "'" || char === '"' || char === '`') { quote = char; continue; }
    if (char !== ';') continue;
    const candidate = sql.slice(start, i + 1).trim();
    if (!trigger) trigger = /(?:^|\n)\s*CREATE\s+TRIGGER\b/i.test(candidate);
    if (trigger && !/\bEND\s*;$/i.test(candidate)) continue;
    if (candidate.replace(/--[^\n]*/g, '').trim()) statements.push(candidate);
    start = i + 1;
    trigger = false;
  }
  if (quote || comment === 'block' || sql.slice(start).replace(/--[^\n]*/g, '').trim()) {
    throw new Error('Incomplete migration SQL');
  }
  return statements;
}

const migrations = names.map((name) => {
  const sql = readFileSync(new URL(name, root), 'utf8');
  return { name, sha256: createHash('sha256').update(sql).digest('hex'), statements: splitSqlStatements(sql) };
});
const generated = `// Generated by tooling/build/generate-migration-bundle.mjs; do not edit.\nexport const MIGRATION_BUNDLE = Object.freeze(${JSON.stringify(migrations, null, 2)});\n`;
if (process.argv.includes('--check')) {
  if (readFileSync(output, 'utf8') !== generated) throw new Error('Migration bundle is stale');
} else {
  writeFileSync(output, generated);
}
